import{_ as t,H as e,f as a,i as o}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"特别加餐 | AI浪潮下：如何让大模型成为我们的助手？","description":"","frontmatter":{},"headers":[{"level":2,"title":"抓住新机遇","slug":"抓住新机遇","link":"#抓住新机遇","children":[]},{"level":2,"title":"获得助手的第一步：用好 Prompt","slug":"获得助手的第一步-用好-prompt","link":"#获得助手的第一步-用好-prompt","children":[{"level":3,"title":"为什么 Prompt 很重要？","slug":"为什么-prompt-很重要","link":"#为什么-prompt-很重要","children":[]},{"level":3,"title":"怎么产出高质量的 Prompt？","slug":"怎么产出高质量的-prompt","link":"#怎么产出高质量的-prompt","children":[]}]}],"relativePath":"Serverless进阶实战课/特别加餐｜AI浪潮下：如何让大模型成为我们的助手？.md","filePath":"Serverless进阶实战课/特别加餐｜AI浪潮下：如何让大模型成为我们的助手？.md","lastUpdated":1795535054000}'),r={name:"Serverless进阶实战课/特别加餐｜AI浪潮下：如何让大模型成为我们的助手？.md"};function i(l,p,s,n,h,m){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="特别加餐-ai浪潮下-如何让大模型成为我们的助手" tabindex="-1">特别加餐 | AI浪潮下：如何让大模型成为我们的助手？ <a class="header-anchor" href="#特别加餐-ai浪潮下-如何让大模型成为我们的助手" aria-label="Permalink to &quot;特别加餐 | AI浪潮下：如何让大模型成为我们的助手？&quot;">​</a></h1><p>你好，我是静远。</p><p>看到评论区好多小伙伴都在说加餐，今天就来一篇热点话题加餐。最近业界谈论最火的话题莫过于“大模型”了，这篇加餐抛砖引玉，和你一块探讨一下这波浪潮。</p><ul><li>根据 UBS 发布的研究报告显示，ChatGPT“出道” 2 个月，月活跃数就已经达到了 1 亿，是历史上用户数增长最快的消费者应用。要知道，风靡用户群体中的 TikTok 花了 9 个月的时间 MAU 才破亿，而 Instagram 则花费了 30 个月的时间。</li></ul><p>ChatGPT 为什么如此引人注目？我梳理了三个要点。</p><p>第一，门槛低。ChatGPT 使用起来非常方便，是 AI“平民化”的里程碑。</p><p>第二，功能全。ChatGPT 包含了更多的主题数据，能够处理更多的场景的任务，比如撰写文章，回答问题、语言翻译、代码辅助编写、专业领域知识回答等，并且具备很强的学习和推理能力。用陆奇博士的话来说“如果 GPT 3 的水平是 between high school and college student，那么 GPT 4 显然是一个能进斯坦福，而且在斯坦福排名靠前的人。”</p><p>第三，市场价值高。正如陆奇博士所说，2022-2023 的拐点，是模型的成本从边际走向固定，大模型是技术核心、产业化基础。比尔·盖茨称赞 ChatGPT：“自 1980 年以来最具革命性的技术进步。”而这样的“拐点”、“变革”，带来的价值是数万亿以上的价值，如果你想创业或者加入创业公司，这是一个新的赛道。</p><p>让我们一起来看一下国际环境的变化。虽然各大公司都在多多少少宣布裁员计划（如微软谷歌在今年年初宣布裁员计划），但他们都加大了在 AI 行业的投入。</p><ul><li>微软在今年 1 月 23 日宣布对 ChatGPT 的开发公司 OpenAI 进行了第三轮投资，将向OpenAI 进行为期多年、金额达数十亿美元的投资，以加速其在人工智能领域的技术突破。不仅如此，微软还发布了基于 GPT 的 New Bing（搜索引擎 + 聊天机器人）、Office 365Copilot。谷歌发布谷歌版 ChatGPT Bard，面对 ChatGPT 的威胁，注资近 4 亿美元投资Anthropic。除此之外，OpenAI ChatGPT Plugins 上线、Midjourney v5 正式发布、Adobe推出了 AI 模型集 Adobe Firefly、Runway Gen2 发布，亚马逊也已经在它的各种工作职能中运用了大模型……</li></ul><p>国内也处于“百家争鸣”的状态。不仅百度腾讯阿里一众科技巨头在积极布局生成式 AI，就连不少宣称隐退的大佬也纷纷亲自下场。随着大厂、创业公司、资本的进场，带来的挑战与机会也越来越多。而我们要关注的不仅仅是模型层面，芯片、数据、infra 等都需要我们跳出来关注，这样在大模型时代到来的今天，你才能做出正确的选择。</p><h2 id="抓住新机遇" tabindex="-1">抓住新机遇 <a class="header-anchor" href="#抓住新机遇" aria-label="Permalink to &quot;抓住新机遇&quot;">​</a></h2><p>我们怎么把握这个时代赋予的机会呢？这里，我想分三个点来聊一聊。</p><ul><li><p>大模型会不会让我们失业？</p></li><li><p>它的影响面在哪里？</p></li><li><p>个人有哪些机会？</p></li></ul><p>首先，大模型会不会让我们失业？</p><p>开门见山，我的结论是不必焦虑，拥抱变化才是最优解。</p><p>拿我们知道的“马车与汽车”例子来说：汽车取代了马车，马车师傅们虽然暂时失业了，但是他们可以去开汽车，或者去汽车厂当工人，可能工作强度更低，收入还会更高。随着新范式、新变革，带来的是工种和角色的变化，大环境我们改变不了，但改变自己还是相对容易的。</p><p>拿程序员来说，ChatGPT 等自然语言处理技术的出现，可以帮助程序员更加高效地完成一些重复、繁琐或简单的工作。我们相应释放出来时间和精力，就可以更加专注于创造性和高附加值的工作。</p><p>所以大模型会让我们失业吗？短期来看，并不会对我们的职业有显著冲击。长期来看，会有一部分拒绝学习并且属于重复工种的人失业。但你既然能看到这篇加餐，相信你是一位有求知欲的同学，大可不必焦虑，按照自己的节奏来就好。</p><p>接着，大模型在哪些行业会产生影响？</p><p>我们这里不聊大厂都在干啥，相信通过铺天盖地的新闻，你已经非常清楚了，这里我来简单展望一下未来。</p><p>举个例子，你可能多多少少都有在线问诊的经历，在线问诊的时候，一般选择一个医生的费用在几十到几百元不等，但也就是只能做一些病情的咨询。</p><p>医疗这种产业本质就是强模型驱动的。一个好的医生就是一个好的模型，一个好的护士也是一个好的模型，如果基于医疗行业构建了一个大模型，兴许就会有一个 doctorGPT 出来。</p><p>那么，我们原来需要花费几十元到几百元不等的咨询费，只需几次的 doctorGPT 对话就出来了，不是很简单么？ 尤其是当前的医疗领域其实是供需不平衡的，如果国家、政府驱动，朝着这方面迈进，相信会对医疗行业带来深远的影响。</p><p>再比如前阵子 ChatGPT 发布与火热，导致美国在线教育巨头 Chegg 股价“巨震”，也能看出对在线教育的冲击：我有问题是问 ChatGPT 还是问老师呢？感觉 ChatGPT 都会？当然，目前的 GPT 有时也会“胡说八道”，但这不影响科技驱动历史的前进。</p><p>不仅如此，科学、金融、工业、物流等各行各业，都会面临一些新的方式、新的范式的挑战。</p><p>但挑战永远与机会共存，这些问题，我们思考得越早，越能发掘潜在的机会和机遇。不管你是创业还是加入一个 AI 工种，哪怕还是目前跟大模型不沾边，但你都要在这次大潮流中抓住机遇。你不能成为一个“不会使用智能手机的老人”，我们还年轻，还可以折腾一下。</p><p>从个人角度看，我们能做啥？</p><ul><li><p>借助大模型，帮助创业团队，快速探索方向，加速想法的迭代、模型的迭代，甚至资源获取。如果你是一把手，那么这个方向你需要重点考虑。</p></li><li><p>借助大模型，提升工作效率，产生更大的个人价值。在面对各种技术问题时，把习惯慢慢变成 “在问 google 之前，先问大模型”。</p></li><li><p>培养自己和大模型交互的习惯和能力。随着大模型的渗透，相信你能感受到 PromptEngineer 这个词的火热。</p></li></ul><p>接下来，我们就进一步聊聊如何让大模型成为我们的助手。</p><h2 id="获得助手的第一步-用好-prompt" tabindex="-1">获得助手的第一步：用好 Prompt <a class="header-anchor" href="#获得助手的第一步-用好-prompt" aria-label="Permalink to &quot;获得助手的第一步：用好 Prompt&quot;">​</a></h2><p>第一个问题，Prompt 是什么呢？</p><p>如果你需要请求别人帮忙，你可能会说：『我需要你帮我拿一下我的行李箱』。同理，当你请求的是一个程序或者一个工具时，你需要输入一串指令。而这种『指令』或者『提示词』其实就是我们所说的 Prompt，也就是给 ChatGPT 等自然语言处理模型提供输入的文本。</p><p>在使用 ChatGPT 进行文本生成、对话或其他任务时，Prompt 正是决定你使用大模型工具输出质量的一个关键因素。Prompt 可以引导模型生成高质量的文本或图像，反之，则可能导致模型输出低质量或无意义的结果。</p><h3 id="为什么-prompt-很重要" tabindex="-1">为什么 Prompt 很重要？ <a class="header-anchor" href="#为什么-prompt-很重要" aria-label="Permalink to &quot;为什么 Prompt 很重要？&quot;">​</a></h3><p>在日常生活中，我们总是很在意沟通的有效性，无论是工作、学习或者一些公共场合，我们总是希望交谈的双方能够快速理解对方的意思是什么，这取决于每一次输出给对方的内容是否足够清晰。</p><p>在我们和大模型交互时，也同样是这样。模糊、不够清晰的 prompt 会使对话偏离预期的轨道，从而导致我们无法获取预期的结果。比如：“请帮我写一篇关于机器学习的文章”，这个Prompt 就过于笼统，没有具体的细节或要求。这可能导致 ChatGPT 输出一些没有价值的文本，因为模型不知道应该在文章中包含哪些信息。</p><p>再比如“请帮我评估这个模型的性能”，这个 Prompt 没有提供任何关于模型的具体信息，例如输入数据、模型架构、评估指标等等。因此，模型很难根据这个 Prompt 生成准确和有意义的评估结果。</p><p>在 AI 绘画时 Prompt 就更加重要了，你需要尽可能地详细，包括画面主体、细节词，风格修饰词，比如下面是用文心一言进行的绘画，描述得越详细，获得的反馈就越符合预期。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%2589%25B9%25E5%2588%25AB%25E5%258A%25A0%25E9%25A4%2590/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%2589%25B9%25E5%2588%25AB%25E5%258A%25A0%25E9%25A4%2590/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%2589%25B9%25E5%2588%25AB%25E5%258A%25A0%25E9%25A4%2590/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%2589%25B9%25E5%2588%25AB%25E5%258A%25A0%25E9%25A4%2590/2.png" alt=""></a></p><h3 id="怎么产出高质量的-prompt" tabindex="-1">怎么产出高质量的 Prompt？ <a class="header-anchor" href="#怎么产出高质量的-prompt" aria-label="Permalink to &quot;怎么产出高质量的 Prompt？&quot;">​</a></h3><p>可以看出 Prompt 对于我们在和大模型交互时非常重要，那我们该如何产出高质量的 Prompt呢？</p><p>我们先来看一些高质量的 Prompt 示例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我需要在北京市海淀区寻找一家自助餐厅，人均消费在500以内，并且提供午餐服务&quot;</span></span></code></pre></div><p>这个 prompt 包含人：『我』 ；事：『寻找餐厅』；地点：『北京海淀』；时间：『提供午餐』以及价格限定：『人均 500』。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;请帮我写一篇介绍机器学习基础概念的文章，需要包括监督学习和无监督学习的基本原理和应用场景&quot;</span></span></code></pre></div><p>这个 Prompt 提供了具体的任务要求和关键词，具体的需求：『机器学习基础概念的文章』，包含的内容：『监督学习和无监督学习』。</p><p>可以看出，在写 Prompt 时，需要清楚地表达想要问的问题或需要模型回答的内容，问题越清晰明了，模型回答的质量也会越高。</p><p>我在这里给你梳理了要用好 Prompt 的五点注意事项。</p><ol><li>提供具体的任务要求和关键词。</li></ol><p>Prompt 需要明确任务要求和关键词，让大模型知道需要完成什么样的任务，以及任务需要包含哪些内容。比如前面提到的『写文章』『找餐厅』等，这些要求和关键词可以在 Prompt 中明确提出，也可以通过上下文或其他方式进行隐含。</p><ol start="2"><li>提供足够的上下文信息。</li></ol><p>Prompt 中应该包含足够的上下文信息，让大模型能够更好地理解任务和生成准确的输出。例如在问答任务中，Prompt 应该包含问题和背景信息；在文本生成任务中，Prompt 应该包含上下文和要生成的文本类型等等，比如『我需要你结合前面给你的这些关键词给我写一篇散文』。</p><ol start="3"><li>给出明确的评估指标。</li></ol><p>Prompt 中应该给出明确的评估指标，让大模型知道如何评估生成的输出是否符合要求。例如在文本生成任务中，评估指标可以是生成文本的流畅度、准确性、相关性等等；在问答任务中，评估指标可以是回答的准确性、信息覆盖率等等。</p><ol start="4"><li>避免过于笼统或模糊的描述。</li></ol><p>过于笼统或模糊的 Prompt 会导致模型输出的结果缺乏具体性或含义，甚至可能是无意义的文本。因此，Prompt 应该尽可能具体和清晰，避免使用过于笼统或模糊的描述。</p><p>5.考虑输入的质量和多样性。</p><p>Prompt 的输入质量和多样性对于模型的生成效果有很大的影响。因此，Prompt 应该尽可能提供高质量、多样性的输入，这样可以帮助模型更好地理解任务和生成高质量的输出。例如，在问答任务中，提供多个不同类型的问题可以帮助模型更好地理解问题类型和生成准确的回答。</p><p>总的来说，编写高质量的 Prompt 是使用 ChatGPT 等自然语言处理模型的关键步骤。好的Prompt 可以帮助模型生成准确、相关、条理性强的文本，而不好的 Prompt 则可能导致模型输出低质量、无意义的结果。因此，我们需要注意提供具体的任务要求和关键词、提供足够的上下文信息、给出明确的评估指标、避免过于笼统或模糊的描述，以及考虑输入的质量和多样性等方面，来编写高质量的 Prompt。</p><p>我们身处大模型的时代，虽然不是每个人都是模型的开发者，但我们完全可以从用好大模型开始、用好 ChatGPT、用好通用大模型之上的垂直大模型，让新的技术革命帮助我们更加高质高效地生活工作，相信在不久的未来，每个人都有一个属于自己的“贴身大模型助手”。</p><p>今天的加餐到这里也就结束了，还是回到我们开篇说的，希望这篇加餐能够引起你的一些思考，也希望你能够在评论区分享你对于大模型的想法，我们一起探讨。留言区见！</p>',63)])])}const d=t(r,[["render",i]]);export{c as __pageData,d as default};
